/**
 * Xiaocao 页面提取：图片 / 视频 / 标题 / 时间
 */

import {
  collectImgSrcs,
  normalizeText,
  pickBestByViewport,
  type VideoMatcher
} from "~utils/page-extract-shared"

function readVideoSrc(video: HTMLVideoElement): string {
  const current = video.currentSrc?.trim()
  if (current) return current

  const attr = video.getAttribute("src")?.trim()
  if (attr) return new URL(attr, document.baseURI).href

  const source = video.querySelector("source")
  if (source instanceof HTMLSourceElement) {
    const sourceAttr = source.getAttribute("src")?.trim()
    if (sourceAttr) return new URL(sourceAttr, document.baseURI).href
    if (source.src) return source.src
  }

  return ""
}

function collectVideoSrcs(root: Element, seen: Set<string>): string[] {
  const videos =
    root instanceof HTMLVideoElement
      ? [root]
      : Array.from(root.querySelectorAll("video"))

  const srcs: string[] = []
  videos.forEach((video) => {
    if (!(video instanceof HTMLVideoElement)) return
    const src = readVideoSrc(video)
    if (!src || seen.has(src) || !/^https?:/i.test(src)) return
    seen.add(src)
    srcs.push(src)
  })
  return srcs
}

/**
 * 内容区内的 video[src] / video > source[src]。
 * 导出非 null 即表示该站点提供视频匹配规则。
 */
export const getXiaoCaoVideos: VideoMatcher = (rootSelector) => {
  const selector = rootSelector.trim() || ".tpc_content.do_not_catch"
  const seen = new Set<string>()
  const srcs: string[] = []

  Array.from(document.querySelectorAll(selector)).forEach((root) => {
    collectVideoSrcs(root, seen).forEach((src) => srcs.push(src))
  })

  return srcs
}

/** 选择器下全部图片（不做视口筛选） */
export function getXiaoCaoImages(imageSelector: string): string[] {
  const rootSelector = imageSelector.trim() || ".tpc_content.do_not_catch"
  const seen = new Set<string>()
  const srcs: string[] = []

  Array.from(document.querySelectorAll(rootSelector)).forEach((root) => {
    collectImgSrcs(root, seen).forEach((src) => srcs.push(src))
  })

  return srcs
}

/** 多个匹配时取视口相交面积最大的文案 */
export function getXiaoCaoTitle(titleSelector: string): string {
  const trimmed = titleSelector.trim() || 'td[valign="top"] h4.f16'
  return pickBestByViewport(
    Array.from(document.querySelectorAll(trimmed)),
    normalizeText
  )
}

/** 从 data-timestamp（秒）* 1000 取毫秒时间戳字符串 */
export function getXiaoCaoTime(timeSelector: string): string {
  const selector = timeSelector.trim() || "tr.tr1 span[data-timestamp]"
  return pickBestByViewport(
    Array.from(document.querySelectorAll(selector)),
    (el) => {
      const tsAttr = el.getAttribute("data-timestamp")
      if (!tsAttr) return ""
      const ms = Number(tsAttr) * 1000
      return Number.isFinite(ms) ? String(ms) : ""
    }
  )
}


